#include "tkl_board_config.h"

// Define which Tuya Port ID is used for Logging (Default to 0)
// NO MAGIC NUMBER: Using constant
#define TUYA_LOG_PORT_ID 0

static UART2_Handle uartHandle = NULL;
#define TKL_LOG_BUFFER_SIZE 256
// --- END: user defines and implements ---

/**
 * @brief Output log information
 *
 * @pre     tkl_log_open has been called
 * @pre     There are no ongoing read or write calls.  Any ongoing read
 * or write calls can be cancelled with UART2_readCancel() or
 * UART2_writeCancel().
 *
 * @param[in] str: log information
 *
 * @note This API is used for outputing log information
 *
 * @return
 */
void tkl_log_output(const char *str, ...)
{
    // --- BEGIN: user implements ---
    if (str == NULL) {
        return;
    }

    if (uartHandle == NULL){
        // UART needs to be opened
        return;
    }

    char log_buf[TKL_LOG_BUFFER_SIZE];
    va_list args;
    va_start(args, str);
    int formatted = vsnprintf(log_buf, sizeof(log_buf), str, args);
    va_end(args);

    if (formatted <= 0) {
        return;
    }

    size_t write_len = (formatted < (int)sizeof(log_buf)) ? (size_t)formatted : (sizeof(log_buf) - 1U);
    size_t bytesWritten = 0;
    UART2_write(uartHandle, log_buf, write_len, &bytesWritten);
    
    return;
    // --- END: user implements ---
}

/**
 * @brief Close log port
 *
 * @pre    tkl_log_open has been called.
 * @pre    There are no ongoing read or write calls.  Any ongoing read
 * or write calls can be cancelled with UART2_readCancel() or
 * UART2_writeCancel().
 *
 * @param void
 *
 * @note This API is used for closing log port.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_log_close(void)
{
    // --- BEGIN: user implements ---
    // TODO Optional: Cancel all ongoing read/write
    // UART2_readCancel(uartHandle)
    // UART2_writeCancel(uartHandle)

    if (uartHandle != NULL) {
        UART2_close(uartHandle);
        uartHandle = NULL;
    }
    
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief Open log port
 *
 * @param void
 *
 * @note This API is used for openning log port.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_log_open(void)
{
    // --- BEGIN: user implements ---
    
    // [MAPPING] Look up TI index for the Log Port (Default 0)
    int16_t ti_log_index = tkl_hw_get_uart_index(TUYA_LOG_PORT_ID);

    // If result is negative, the Application did not map the Log UART.
    if (ti_log_index < 0) {
        return OPRT_NOT_SUPPORTED;
    }

    UART2_Params params;
    UART2_Params_init(&params);
    
    params.baudRate = 115200; // Standard Log Baudrate (Or make configurable)
    params.writeMode = UART2_Mode_BLOCKING;

    // TODO TKL : Lock object like in uart_temn and osi_dpl
    // osi_LockObjCreate(&LockObj);

    uartHandle = UART2_open(ti_log_index, &params);

    if (uartHandle == NULL) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}
